ANALYTICS_DASHBOARD = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Market Analytics</title><style>
:root{color-scheme:dark;background:#0b0f14;color:#e7edf5;font-family:system-ui,sans-serif}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1480px;margin:auto;padding:24px}.muted{color:#91a0b4}.error{color:#ff8a8a}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}.toolbar input,.toolbar button{width:auto;border:1px solid #34445d;border-radius:8px;background:#0b111a;color:#e7edf5;padding:8px 10px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.panel{background:#121923;border:1px solid #243044;border-radius:12px;padding:16px;margin-bottom:16px;overflow:auto}.wide{grid-column:1/-1}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{padding:8px;border-bottom:1px solid #243044;text-align:left}th{color:#91a0b4}a{color:#70b7ff;text-decoration:none}.score{font-weight:700}.pill{display:inline-block;border:1px solid #34445d;border-radius:999px;padding:2px 7px}svg{width:100%;height:180px;background:#0b111a;border-radius:8px}@media(max-width:900px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}}
</style></head><body><div class="wrap"><a href="/">← Dashboard</a><h1>Market Analytics</h1><div class="muted">Observed Marketplace events support decisions but do not prove inventory, sales, or conversion.</div><div class="toolbar"><label>Window <input id="days" type="number" min="1" max="365" value="30"> days</label><button onclick="loadAnalytics()">Refresh</button><span id="status" class="muted"></span></div><div class="grid"><section class="panel wide"><h2>Collection trend</h2><div id="trend"></div></section><section class="panel"><h2>Category intelligence</h2><div id="categories"></div></section><section class="panel"><h2>Top opportunities</h2><div id="opportunities"></div></section><section class="panel wide"><h2>Watchlist effectiveness</h2><div id="watchlists"></div></section></div></div><script>
const esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));const fmt=v=>v==null?'—':Number(v).toFixed(2);async function api(url){const r=await fetch(url);if(!r.ok)throw new Error((await r.json()).detail||r.statusText);return r.json()}
function chart(rows){if(!rows.length)return '<div class="muted">No collection runs in this window.</div>';const values=rows.map(x=>Number(x.new_listings));const max=Math.max(1,...values);const w=900,h=180,p=25;const pts=values.map((v,i)=>[p+i*(w-2*p)/Math.max(1,values.length-1),h-p-v/max*(h-2*p)]);return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="New listings by day"><polyline fill="none" stroke="#70b7ff" stroke-width="3" points="${pts.map(x=>x.join(',')).join(' ')}"/>${pts.map((x,i)=>`<circle cx="${x[0]}" cy="${x[1]}" r="4" fill="#6ee7a0"><title>${esc(rows[i].bucket)}: ${values[i]} new listings</title></circle>`).join('')}</svg><div class="muted">New listings per collection day; omissions do not imply sales.</div>`}
function table(headers,rows){if(!rows.length)return '<div class="muted">No observations in this window.</div>';return '<table><thead><tr>'+headers.map(x=>'<th>'+esc(x[0])+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+headers.map(x=>'<td>'+x[1](r)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
async function loadAnalytics(){const days=Math.max(1,Math.min(365,Number(document.getElementById('days').value)||30));document.getElementById('status').textContent='Loading analytics…';try{const [trends,categories,watchlists,opportunities]=await Promise.all([api(`/api/analytics/trends?days=${days}`),api(`/api/analytics/categories?days=${days}`),api(`/api/analytics/watchlists?days=${days}`),api(`/api/analytics/opportunities?days=${days}&limit=25`)]);document.getElementById('trend').innerHTML=chart(trends.collection);document.getElementById('categories').innerHTML=table([['Category',x=>esc(x.category)],['Currency',x=>esc(x.currency)],['Listings',x=>esc(x.listings)],['Median',x=>fmt(x.median_price)],['P25–P75',x=>fmt(x.p25_price)+'–'+fmt(x.p75_price)],['High score',x=>Math.round(Number(x.high_score_rate||0)*100)+'%']],categories);document.getElementById('opportunities').innerHTML=table([['Listing',x=>`<a href="/listing/${encodeURIComponent(x.listing_id)}">${esc(x.title)}</a>`],['Price',x=>esc(x.latest_price_text)],['Adjusted',x=>'<span class="score">'+fmt(x.opportunity_score)+'</span>'],['Drop',x=>x.price_drop_pct==null?'—':Math.round(x.price_drop_pct*100)+'%']],opportunities);document.getElementById('watchlists').innerHTML=table([['Watchlist',x=>esc(x.name)],['Matches',x=>esc(x.total_matches)],['New',x=>esc(x.new_matches)],['Target hits',x=>esc(x.target_hits)],['Notifications',x=>esc(x.notifications)],['Mean score',x=>fmt(x.mean_score)],['Health',x=>x.last_error?'<span class="error">error</span>':'<span class="pill">ok</span>']],watchlists);document.getElementById('status').textContent='Updated';}catch(e){document.getElementById('status').innerHTML='<span class="error">'+esc(e.message)+'</span>'}}
loadAnalytics();
</script></body></html>"""
